create extension if not exists pgcrypto;
create type public.order_status as enum ('draft','incoming','in_production','ready','out_for_delivery');
create type public.order_type as enum ('dine_in','takeout','delivery');
create type public.payment_method as enum ('cash','pix','credit_card','debit_card');
create type public.order_source as enum ('web','whatsapp');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text, role text not null default 'staff' check(role in('owner','manager','staff')), created_at timestamptz not null default now());
create table public.menu_categories(id uuid primary key default gen_random_uuid(),name text not null unique,sort_order int not null default 0,active boolean not null default true);
create table public.menu_items(id uuid primary key default gen_random_uuid(),category_id uuid references public.menu_categories(id) on delete set null,name text not null,description text,price numeric(10,2) not null check(price>=0),image_url text,active boolean not null default true,created_at timestamptz not null default now());
create table public.orders(id uuid primary key default gen_random_uuid(),order_number text unique not null,tracking_token uuid unique not null default gen_random_uuid(),created_at timestamptz not null default now(),customer_name text not null,phone text not null,address text,ticket text,special_notes text,order_type public.order_type not null,payment_method public.payment_method not null,status public.order_status not null default 'draft',total numeric(10,2) not null default 0 check(total>=0),source public.order_source not null default 'web');
create table public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,menu_item_id uuid references public.menu_items(id) on delete set null,item_name text not null,quantity int not null check(quantity>0),unit_price numeric(10,2) not null,subtotal numeric(10,2) generated always as (quantity*unit_price) stored,notes text);
create table public.order_status_history(id bigint generated always as identity primary key,order_id uuid not null references public.orders(id) on delete cascade,old_status public.order_status,new_status public.order_status not null,changed_by uuid references auth.users(id),created_at timestamptz not null default now());
create sequence public.order_number_seq;
create or replace function public.next_order_number() returns text language sql security definer set search_path=public as $$select 'ORD-'||to_char(now(),'YYYYMMDD')||'-'||lpad(nextval('public.order_number_seq')::text,5,'0')$$;
create or replace function public.create_customer_order(payload jsonb) returns jsonb language plpgsql security definer set search_path=public as $$declare new_order orders; line jsonb; mi menu_items; computed_total numeric:=0; begin
if jsonb_array_length(payload->'items')=0 then raise exception 'Cart cannot be empty'; end if;
insert into orders(order_number,customer_name,phone,address,special_notes,order_type,payment_method,source) values(next_order_number(),payload->>'customer_name',payload->>'phone',nullif(payload->>'address',''),nullif(payload->>'special_notes',''),(payload->>'order_type')::order_type,(payload->>'payment_method')::payment_method,'web') returning * into new_order;
for line in select * from jsonb_array_elements(payload->'items') loop select * into mi from menu_items where id=(line->>'menu_item_id')::uuid and active=true; if not found then raise exception 'Unavailable menu item'; end if; insert into order_items(order_id,menu_item_id,item_name,quantity,unit_price,notes) values(new_order.id,mi.id,mi.name,(line->>'quantity')::int,mi.price,line->>'notes'); computed_total:=computed_total+mi.price*(line->>'quantity')::int; end loop;
update orders set total=computed_total,ticket='Ticket '||new_order.order_number where id=new_order.id; return jsonb_build_object('id',new_order.id,'order_number',new_order.order_number,'tracking_token',new_order.tracking_token); end$$;
create or replace function public.get_order_by_tracking_token(token_input uuid) returns jsonb language sql security definer set search_path=public as $$select to_jsonb(o) from orders o where tracking_token=token_input$$;
create or replace function public.log_status_change() returns trigger language plpgsql security definer set search_path=public as $$begin if old.status is distinct from new.status then insert into order_status_history(order_id,old_status,new_status,changed_by) values(new.id,old.status,new.status,auth.uid()); end if; return new; end$$;
create trigger order_status_audit after update of status on orders for each row execute function log_status_change();
alter table profiles enable row level security;alter table menu_categories enable row level security;alter table menu_items enable row level security;alter table orders enable row level security;alter table order_items enable row level security;alter table order_status_history enable row level security;
create policy "public reads active categories" on menu_categories for select using(active);
create policy "public reads active menu" on menu_items for select using(active);
create policy "staff reads orders" on orders for select to authenticated using(exists(select 1 from profiles p where p.id=auth.uid()));
create policy "staff updates orders" on orders for update to authenticated using(exists(select 1 from profiles p where p.id=auth.uid())) with check(exists(select 1 from profiles p where p.id=auth.uid()));
create policy "staff reads order items" on order_items for select to authenticated using(exists(select 1 from profiles p where p.id=auth.uid()));
grant execute on function create_customer_order(jsonb) to anon,authenticated;grant execute on function get_order_by_tracking_token(uuid) to anon,authenticated;
alter publication supabase_realtime add table orders;
